export const apiRouter = express.Router();
apiRouter.use(express.json({limit:'1mb'}));
const imageTypes=['image/jpeg','image/png','image/webp'];
const upload=multer({storage:multer.memoryStorage(),limits:{fileSize:2_000_000},fileFilter:(_r,f,cb)=>imageTypes.includes(f.mimetype)?cb(null,true):cb(new Error('Format file harus JPG, PNG, atau WebP.'))});
const rates=new Map<string,{count:number,reset:number}>();
function limited(key:string,max:number,ms:number){const now=Date.now(),x=rates.get(key);if(!x||x.reset<now){rates.set(key,{count:1,reset:now+ms});return false;}if(x.count>=max)return true;x.count++;return false;}
const asyncRoute=(fn:any)=>(req:any,res:any,next:any)=>Promise.resolve(fn(req,res,next)).catch(next);
function bearer(req:express.Request){const h=req.headers.authorization||'';return h.startsWith('Bearer ')?h.slice(7):'';}
async function requireAdmin(req:express.Request,res:express.Response,next:express.NextFunction){const user=await assertOwner(bearer(req));if(!user)return res.status(403).json({error:'Akses tidak diizinkan. Silakan login kembali di /Entrance.'});res.locals.owner=user;next();}
function token(req:express.Request){return String(req.headers['x-reservation-token']||req.body?.sessionToken||'');}
function dbError(res:express.Response,e:any,status=400){const code=String(e?.message||'DATABASE_ERROR');return res.status(status).json({code,error:humanError(code)});}
function humanError(code:string){const messages:Record<string,string>={SHIPPING_ORIGIN_INVALID:'Alamat asal pengiriman belum valid.',SHIPPING_ORIGIN_CHANGED:'Alamat asal berubah. Jangan membayar ulang; pilih ulang layanan atau hubungi owner bila sudah membayar.',INSUFFICIENT_STOCK:'Stok tidak mencukupi.',VOUCHER_INVALID:'Voucher tidak tersedia, tidak aktif, atau kuotanya habis.',VOUCHER_SCOPE_INVALID:'Voucher tidak berlaku untuk isi keranjang ini.',RESERVATION_NOT_FOUND:'Reservasi tidak ditemukan.',RESERVATION_NOT_ACTIVE:'Reservasi sudah tidak aktif.',RESERVATION_EXPIRED:'Reservasi sudah kedaluwarsa.',RESERVATION_REQUIRES_RECOVERY:'Reservasi perlu dipulihkan. Jangan membuat pembayaran baru; hubungi owner bila sudah membayar.',RETURN_WINDOW_CLOSED:'Retur hanya dapat diajukan setelah pesanan diterima dan paling lambat 7 hari sejak tanggal barang diterima.',ORDER_NOT_FOUND:'Pesanan tidak ditemukan. Pastikan Nomor Pesanan, email, dan WhatsApp sama persis dengan data checkout.',ORDER_IDENTITY_MISMATCH:'Nomor pesanan, email, atau WhatsApp tidak cocok.',INVALID_RETURN_ITEM:'Barang atau jumlah retur tidak sesuai dengan pesanan.'};return messages[code]||code;}
function reservationDto(r:any){return {id:r.id,expiresAt:r.expires_at,items:(r.reservation_items||[]).map((i:any)=>({productId:i.product_id,variantId:i.variant_id,productName:i.product_name,color:i.color_name,size:i.size_name,unitPrice:Number(i.unit_price),weightGrams:i.weight_grams,imageUrl:publicStorageUrl(i.image_path),quantity:i.quantity})),subtotal:Number(r.subtotal),discountAmount:Number(r.discount_amount),voucherId:r.voucher_id,shippingFee:Number(r.shipping_fee),shippingService:r.shipping_service_label,destinationId:r.destination_id,shippingOriginId:r.shipping_origin_id,totalAmount:Number(r.total_amount),status:r.status,createdAt:r.created_at,paymentMethod:r.payment_method};}
function orderDto(o:any){const p=o.payments?.[0];return {id:o.id,orderNumber:o.order_number,reservationId:o.reservation_id,customerName:o.customer_name,customerEmail:o.customer_email,customerWhatsapp:o.customer_whatsapp,customerBirthDate:o.customer_birth_date,addressLine:o.address_line,province:o.province,city:o.city,subdistrict:o.subdistrict,village:o.village,postalCode:o.postal_code,subtotal:Number(o.subtotal),discount:Number(o.discount_amount),shippingFee:Number(o.shipping_fee),shippingService:o.shipping_service_label,totalAmount:Number(o.total_amount),paymentMethod:o.payment_method,paymentStatus:o.payment_status,fulfillmentStatus:o.fulfillment_status,paymentProofUrl:p?.signedUrl||'',paymentProofMime:p?.proof_mime||'',rejectionReason:o.rejection_reason,rejectionDeadline:o.rejection_deadline,actualDeliveryDate:o.actual_delivery_date,createdAt:o.created_at,updatedAt:o.updated_at,refundAmount:Number(o.refund_amount||0),refundReason:o.refund_reason,cancellationReason:o.cancellation_reason,items:(o.order_items||[]).map((x:any)=>({id:x.id,variantId:x.variant_id,productName:x.product_name,color:x.color_name,size:x.size_name,unitPrice:Number(x.unit_price),quantity:x.quantity,subtotal:Number(x.line_total),allocatedBatches:(x.order_fifo_allocations||[]).map((a:any)=>({batchId:a.batch_id,quantity:a.quantity,costPerUnit:Number(a.cost_per_unit)}))})),costs:Array.isArray(o.order_costs)?o.order_costs[0]:o.order_costs};}
async function uploadFile(bucket:string,file:Express.Multer.File,prefix:string){const ext=({ 'image/jpeg':'jpg','image/png':'png','image/webp':'webp','application/pdf':'pdf'} as any)[file.mimetype];if(!ext)throw new Error('Format file tidak didukung.');const path=`${prefix}/${crypto.randomUUID()}.${ext}`;const {error}=await getSupabaseAdmin().storage.from(bucket).upload(path,file.buffer,{contentType:file.mimetype,upsert:false});if(error)throw error;return path;}
function catalogPath(value:string){const marker='/storage/v1/object/public/catalog-media/';const at=value.indexOf(marker);return at>=0?decodeURIComponent(value.slice(at+marker.length)):value;}

const PUBLIC_CACHE_TTL_MS=60_000;
const publicDataCache=new Map<string,{expiresAt:number,value:any}>();
const publicDataInFlight=new Map<string,Promise<any>>();
let publicCacheGeneration=0;
async function cachedPublic<T>(key:string,loader:()=>Promise<T>):Promise<T>{const cached=publicDataCache.get(key);if(cached&&cached.expiresAt>Date.now())return cached.value;const running=publicDataInFlight.get(key);if(running)return running;const generation=publicCacheGeneration;const promise=loader().then(value=>{if(generation===publicCacheGeneration)publicDataCache.set(key,{value,expiresAt:Date.now()+PUBLIC_CACHE_TTL_MS});return value;}).finally(()=>{if(publicDataInFlight.get(key)===promise)publicDataInFlight.delete(key);});publicDataInFlight.set(key,promise);return promise;}
function invalidatePublicDataCache(){publicCacheGeneration++;publicDataCache.clear();publicDataInFlight.clear();}
const publicResponse=(res:express.Response)=>res.setHeader('Cache-Control','no-store');

apiRouter.get('/public/bootstrap',asyncRoute(async(_req:any,res:any)=>{publicResponse(res);const [settings,categories,products,content]=await Promise.all([cachedPublic('settings',()=>repository.publicSettings()),cachedPublic('categories',()=>repository.categories()),cachedPublic('products',()=>repository.products(false,false)),cachedPublic('content',()=>repository.content())]);res.json({settings,categories,featuredProducts:products,...content});}));
apiRouter.get('/public/settings',asyncRoute(async(_req:any,res:any)=>{publicResponse(res);res.json({settings:await cachedPublic('settings',()=>repository.publicSettings())});}));
apiRouter.get('/public/categories',asyncRoute(async(_req:any,res:any)=>{publicResponse(res);res.json({categories:await cachedPublic('categories',()=>repository.categories())});}));
apiRouter.get('/public/content',asyncRoute(async(_req:any,res:any)=>{publicResponse(res);res.json(await cachedPublic('content',()=>repository.content()));}));
apiRouter.get('/public/products',asyncRoute(async(req:any,res:any)=>{publicResponse(res);let items=[...await cachedPublic<any[]>('products',()=>repository.products(false,false))];const q=String(req.query.search||'').toLowerCase(),category=String(req.query.category||'');if(category)items=items.filter((p:any)=>p.categoryId===category);if(q)items=items.filter((p:any)=>p.name.toLowerCase().includes(q)||p.description.toLowerCase().includes(q));if(req.query.sort==='price_asc')items.sort((a:any,b:any)=>a.basePrice-b.basePrice);if(req.query.sort==='price_desc')items.sort((a:any,b:any)=>b.basePrice-a.basePrice);if(req.query.sort==='bestseller')items.sort((a:any,b:any)=>(b.totalSoldUnits||0)-(a.totalSoldUnits||0));res.json({products:items});}));
apiRouter.get('/public/products/:id',asyncRoute(async(req:any,res:any)=>{const product=await repository.product(req.params.id);if(!product)return res.status(404).json({error:'Produk tidak ditemukan.'});res.json({product});}));

apiRouter.get('/shipping/destinations',asyncRoute(async(req:any,res:any)=>{const q=String(req.query.search||req.query.q||'').trim();if(q.length<3)return res.json({destinations:[]});const key=process.env.RAJAONGKIR_API_KEY?.trim();if(!key)return res.status(503).json({code:'AUTHENTICATION_FAILED',error:'RajaOngkir belum dikonfigurasi di server.'});const out=await searchDestinations(q,key);if(!out.success)return res.status(out.isQuotaExceeded?429:502).json({code:out.isQuotaExceeded?'QUOTA_EXCEEDED':'UPSTREAM_ERROR',error:out.error});res.json({destinations:out.destinations,fromCache:out.fromCache});}));
async function shippingContext(items:any[]){const settings:any=await repository.settings(true);if(!settings?.origin_destination_id)throw new Error('SHIPPING_ORIGIN_INVALID');const products:any[]=await repository.products(true);let weight=Number(settings.packaging_weight_grams||0);for(const item of items){const p=products.find(x=>x.id===item.productId),v=p?.variants.find((x:any)=>x.id===item.variantId);if(!p||!v||!v.isActive)throw new Error('VARIANT_UNAVAILABLE');weight+=p.weightGrams*Number(item.quantity||0);}return {settings,weight:Math.max(1,weight)};}
apiRouter.post('/shipping/calculate',asyncRoute(async(req:any,res:any)=>{if(limited(`ship:${req.ip}`,30,60000))return res.status(429).json({error:'Terlalu banyak permintaan cek ongkir.'});const {destinationId,items}=req.body;if(!destinationId||!Array.isArray(items)||!items.length)return res.status(400).json({error:'Tujuan dan isi keranjang wajib tersedia.'});try{const {settings,weight}=await shippingContext(items);const key=process.env.RAJAONGKIR_API_KEY?.trim();if(!key)return res.status(503).json({code:'AUTHENTICATION_FAILED',error:'RajaOngkir belum dikonfigurasi di server.'});const out=await calculateShippingCost(settings.origin_destination_id,destinationId,weight,key);if(!out.success||!out.services?.length){const status=out.code==='QUOTA_EXCEEDED'?429:out.code==='INVALID_LOCATION'||out.code==='NO_SUPPORTED_SERVICE'?422:out.code==='AUTHENTICATION_FAILED'?503:502;return res.status(status).json({code:out.code||'UPSTREAM_ERROR',error:out.error||'Tidak ada layanan JNE yang tersedia untuk rute ini.'});}res.json({origin:settings.origin_label,originCityId:settings.origin_destination_id,destinationId,calculatedWeightGrams:weight,services:out.services,fromCache:out.fromCache});}catch(e){dbError(res,e);}}));

async function verifiedQuote(body:any){const {settings,weight}=await shippingContext(body.items);const key=process.env.RAJAONGKIR_API_KEY?.trim();if(!key)throw new Error('AUTHENTICATION_FAILED');const out=await calculateShippingCost(settings.origin_destination_id,body.destinationId,weight,key);if(!out.success)throw new Error(out.code||'SHIPPING_VERIFICATION_FAILED');const matched=out.services?.find(x=>x.service===body.shippingService||x.serviceCode===body.shippingService);if(!matched)throw new Error('INVALID_SHIPPING_SERVICE');if(Number(matched.cost)!==Number(body.shippingFee))throw new Error('SHIPPING_FEE_MISMATCH');return {settings,matched,weight};}
apiRouter.post('/vouchers/validate',asyncRoute(async(req:any,res:any)=>{const code=String(req.body.code||'').toUpperCase();const {data:v,error}=await getSupabaseAdmin().from('vouchers').select('*').eq('code',code).eq('is_active',true).maybeSingle();if(error)throw error;if(!v)return res.status(404).json({error:'Kode voucher tidak ditemukan atau tidak aktif.'});if(new Date(v.starts_at)>new Date()||new Date(v.ends_at)<new Date()||v.used_count+v.reserved_quota>=v.quota)return res.status(400).json({error:'Voucher tidak berlaku atau kuotanya habis.'});const subtotal=Number(req.body.subtotal||0);let discount=v.discount_type==='NOMINAL'?Number(v.discount_value):subtotal*Number(v.discount_value)/100;discount=Math.min(subtotal,discount,v.max_discount_amount==null?discount:Number(v.max_discount_amount));res.json({valid:true,code:v.code,promoName:v.promo_name,discountAmount:discount});}));
async function saveReservation(req:any,res:any,id:string|null){if(!token(req))return res.status(401).json({error:'Sesi checkout tidak valid.'});try{const q=await verifiedQuote(req.body);const destination=getKnownDestination(req.body.destinationId);const requestKey=crypto.createHash('sha256').update(JSON.stringify({origin:String(q.settings.origin_destination_id),items:req.body.items.map((x:any)=>({variantId:x.variantId,quantity:x.quantity})).sort((a:any,b:any)=>a.variantId.localeCompare(b.variantId)),destinationId:String(req.body.destinationId),service:q.matched.serviceCode||q.matched.service,fee:Number(q.matched.cost),voucher:String(req.body.voucherCode||'').toUpperCase()})).digest('hex');const data=await repository.reserve({p_reservation_id:id,p_session_token:token(req),p_request_key:requestKey,p_items:req.body.items,p_shipping_origin_id:String(q.settings.origin_destination_id),p_destination_id:String(req.body.destinationId),p_destination_label:destination?.label||String(req.body.destinationLabel||req.body.destinationId),p_provider:q.matched.provider||'JNE',p_service_code:q.matched.serviceCode||q.matched.service,p_service_label:q.matched.service,p_shipping_fee:q.matched.cost,p_shipping_etd:q.matched.etd||'',p_voucher_code:req.body.voucherCode||null});res.json({reservation:{...data,items:req.body.items,createdAt:new Date().toISOString()}});}catch(e){dbError(res,e,String((e as any).message).includes('ORIGIN_CHANGED')?409:400);}}
apiRouter.post('/reservations',asyncRoute(async(req:any,res:any)=>saveReservation(req,res,null)));
apiRouter.put('/reservations/:id',asyncRoute(async(req:any,res:any)=>saveReservation(req,res,req.params.id)));
apiRouter.get('/reservations/:id',asyncRoute(async(req:any,res:any)=>{if(!token(req))return res.status(401).json({valid:false,error:'Sesi checkout tidak valid.'});const row=await repository.reservation(req.params.id,token(req));if(!row)return res.status(404).json({valid:false,code:'RESERVATION_NOT_FOUND',error:'Reservasi tidak ditemukan.'});if(row.status!=='ACTIVE'||new Date(row.expires_at)<=new Date())return res.status(400).json({valid:false,code:`RESERVATION_${row.status}`,error:'Reservasi sudah tidak aktif.'});res.json({valid:true,reservation:reservationDto(row)});}));
const qrisMerchantPayload=()=>process.env.QRIS_MERCHANT_PAYLOAD?.trim()||DEFAULT_DEFRA_QRIS_STATIC_PAYLOAD;
apiRouter.post('/payments/qris',asyncRoute(async(req:any,res:any)=>{const session=token(req);if(!session)return res.status(401).json({error:'Sesi checkout tidak valid.'});const row=await repository.reservation(req.body.reservationId,session);if(!row||row.status!=='ACTIVE'||row.payment_method!=='QRIS')return res.status(409).json({error:'Reservasi atau metode pembayaran belum sesuai.'});const payload=qrisMerchantPayload();validateBaseQRISPayload(payload);const generated=generateDynamicQRISPayload(payload,Number(row.total_amount),{pointOfInitiation:'12'});res.json({reservationId:row.id,totalAmount:Number(row.total_amount),dataUrl:await generateQRDataURL(generated.payload,360)});}));

apiRouter.post('/orders/finalize',upload.single('paymentProof'),asyncRoute(async(req:any,res:any)=>{if(!req.file)return res.status(400).json({error:'Bukti pembayaran wajib diunggah, maksimal 2 MB.'});let path='';try{path=await uploadFile('payment-proofs',req.file,'orders');const order=await repository.finalize({p_reservation_id:req.body.reservationId,p_session_token:req.body.sessionToken,p_customer:{name:req.body.customerName,email:req.body.customerEmail,whatsapp:req.body.customerWhatsapp,birthDate:req.body.customerBirthDate,addressLine:req.body.addressLine,province:req.body.province,city:req.body.city,subdistrict:req.body.subdistrict,village:req.body.village||req.body.subdistrict,postalCode:req.body.postalCode},p_proof_path:path,p_proof_mime:req.file.mimetype});if(order.error){await getSupabaseAdmin().storage.from('payment-proofs').remove([path]);path='';return res.status(409).json({code:order.error,error:humanError(order.error)});}if(order.alreadyFinalized){await getSupabaseAdmin().storage.from('payment-proofs').remove([path]);path='';}const settings:any=await repository.settings();const draft=`Pesanan ${order.orderNumber} telah dibuat. Bukti pembayaran menunggu verifikasi owner.`;res.json({orderNumber:order.orderNumber,order,whatsappDraftText:draft,whatsappNumber:settings.whatsappNumber});}catch(e){if(path)await getSupabaseAdmin().storage.from('payment-proofs').remove([path]);dbError(res,e);}}));
apiRouter.post('/orders/check-status',asyncRoute(async(req:any,res:any)=>{if(limited(`status:${req.ip}`,10,60000))return res.status(429).json({error:'Batas cek status tercapai. Coba lagi dalam 1 menit.'});const input=String(req.body.query??'');if(!input)return res.status(400).json({error:'Masukkan nomor pesanan, email, atau WhatsApp.'});const db=getSupabaseAdmin(),fields='id,order_number,payment_status,fulfillment_status,tracking_number,created_at,updated_at';const results=await Promise.all([db.from('orders').select(fields).eq('order_number',input),db.from('orders').select(fields).eq('customer_email',input),db.from('orders').select(fields).eq('customer_whatsapp',input)]);for(const r of results)if(r.error)throw r.error;const unique=new Map<string,any>();for(const r of results)for(const o of r.data||[])unique.set(o.id,o);const data=[...unique.values()].sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));if(!data.length)return res.status(404).json({error:'Pesanan tidak ditemukan.'});res.json({orders:data.map((o:any)=>({orderNumber:o.order_number,paymentStatus:o.payment_status,fulfillmentStatus:o.fulfillment_status,trackingNumber:o.tracking_number,createdAt:o.created_at,updatedAt:o.updated_at}))});}));
const invoiceOrderSelect='*,order_items(id,product_name,color_name,size_name,unit_price,quantity,line_total),payments(status,verified_at)';
apiRouter.post('/orders/invoice-access',asyncRoute(async(req:any,res:any)=>{
  if(limited(`invoice-access:${req.ip}`,5,60000))return res.status(429).json({error:'Terlalu banyak percobaan verifikasi invoice. Coba lagi dalam 1 menit.'});
  const orderNumber=String(req.body.orderNumber??''),email=String(req.body.email??''),whatsapp=String(req.body.whatsapp??'');
  if(!orderNumber||!email||!whatsapp)return res.status(400).json({error:'Nomor pesanan, email, dan WhatsApp wajib diisi persis seperti saat checkout.'});
  const db=getSupabaseAdmin();
  const {data:order,error}=await db.from('orders').select('id,payment_status').eq('order_number',orderNumber).eq('customer_email',email).eq('customer_whatsapp',whatsapp).maybeSingle();
  if(error)throw error;
  if(!order)return res.status(404).json({code:'ORDER_IDENTITY_MISMATCH',error:humanError('ORDER_IDENTITY_MISMATCH')});
  if(order.payment_status!=='VERIFIED')return res.status(409).json({code:'PAYMENT_NOT_VERIFIED',error:'Invoice tersedia setelah pembayaran diverifikasi admin.'});
  const accessToken=crypto.randomBytes(32).toString('base64url');
  const tokenHash=crypto.createHash('sha256').update(accessToken).digest('hex');
  const expiresAt=new Date(Date.now()+15*60_000).toISOString();
  const {error:saveError}=await db.from('order_invoice_access').upsert({order_id:order.id,token_hash:tokenHash,expires_at:expiresAt,updated_at:new Date().toISOString()},{onConflict:'order_id'});
  if(saveError)throw saveError;
  res.setHeader('Cache-Control','no-store');
  res.json({accessToken,expiresAt});
}));
apiRouter.post('/orders/invoice',asyncRoute(async(req:any,res:any)=>{
  if(limited(`invoice-download:${req.ip}`,10,60000))return res.status(429).json({error:'Terlalu banyak permintaan invoice. Coba lagi dalam 1 menit.'});
  const orderNumber=String(req.body.orderNumber??''),accessToken=String(req.body.accessToken??'');
  if(!orderNumber||!accessToken)return res.status(400).json({error:'Akses invoice tidak valid.'});
  const db=getSupabaseAdmin(),tokenHash=crypto.createHash('sha256').update(accessToken).digest('hex');
  const {data:access,error:accessError}=await db.from('order_invoice_access').select('order_id,expires_at').eq('token_hash',tokenHash).gt('expires_at',new Date().toISOString()).maybeSingle();
  if(accessError)throw accessError;
  if(!access)return res.status(403).json({error:'Akses invoice sudah tidak berlaku. Verifikasi ulang data pesanan.'});
  const {data:order,error}=await db.from('orders').select(invoiceOrderSelect).eq('id',access.order_id).eq('order_number',orderNumber).eq('payment_status','VERIFIED').maybeSingle();
  if(error)throw error;
  if(!order)return res.status(404).json({error:'Invoice tidak tersedia.'});
  const pdf=await createInvoicePdf(order);
  res.setHeader('Cache-Control','private, no-store');
  res.setHeader('Content-Type','application/pdf');
  res.setHeader('Content-Disposition',`attachment; filename="invoice-${orderNumber.replace(/[^A-Za-z0-9_-]/g,'')}.pdf"`);
  res.send(pdf);
}));
apiRouter.post('/returns/submit',upload.array('proofs',5),asyncRoute(async(req:any,res:any)=>{const body=req.body;let items:any=null;if(body.items){try{items=JSON.parse(body.items);}catch{return res.status(400).json({error:'Daftar barang retur tidak valid.'});}}const {data,error}=await getSupabaseAdmin().rpc('submit_return_request',{p_order_number:body.orderNumber,p_email:body.customerEmail,p_whatsapp:body.customerWhatsapp,p_resolution:body.requestedResolution,p_reason:body.reasonCategory,p_notes:body.customerNotes,p_items:items});if(error)return dbError(res,error);const uploaded:string[]=[];try{for(const file of (req.files as Express.Multer.File[]||[])){const path=await uploadFile('return-proofs',file,`returns/${data.id}`);uploaded.push(path);const {error:e}=await getSupabaseAdmin().from('return_proofs').insert({return_id:data.id,storage_path:path});if(e)throw e;}res.json({returnRequest:data});}catch(e){if(uploaded.length)await getSupabaseAdmin().storage.from('return-proofs').remove(uploaded);await getSupabaseAdmin().from('return_requests').delete().eq('id',data.id);throw e;}}));

const refreshCookie=(req:express.Request)=>decodeURIComponent((req.headers.cookie||'').split(';').map(x=>x.trim()).find(x=>x.startsWith('defra_refresh='))?.slice('defra_refresh='.length)||'');
const setRefreshCookie=(res:express.Response,value:string)=>res.cookie('defra_refresh',value,{httpOnly:true,sameSite:'strict',secure:process.env.NODE_ENV==='production',path:'/api/auth',maxAge:30*24*60*60*1000});
apiRouter.post('/auth/login',asyncRoute(async(req:any,res:any)=>{if(limited(`login:${req.ip}`,5,300000))return res.status(429).json({error:'Terlalu banyak percobaan. Coba lagi dalam 5 menit.'});const {data,error}=await getSupabaseAuth().auth.signInWithPassword({email:String(req.body.email||''),password:String(req.body.password||'')});if(error||!data.session)return res.status(401).json({error:'Kredensial login tidak sah. Akses ditolak.'});const owner=await assertOwner(data.session.access_token);if(!owner)return res.status(403).json({error:'Akun ini bukan owner Defra Hijab.'});setRefreshCookie(res,data.session.refresh_token);await repository.audit('LOGIN_SUCCESS','AUTH',owner.id,owner.id);res.json({success:true,token:data.session.access_token,expiresAt:data.session.expires_at,role:'OWNER'});}));
apiRouter.post('/auth/refresh',asyncRoute(async(req:any,res:any)=>{const refresh=refreshCookie(req);if(!refresh)return res.status(401).json({error:'Sesi owner tidak tersedia.'});const {data,error}=await getSupabaseAuth().auth.refreshSession({refresh_token:refresh});if(error||!data.session)return res.status(401).json({error:'Sesi owner berakhir. Silakan masuk kembali.'});if(!await assertOwner(data.session.access_token))return res.status(403).json({error:'Akun bukan owner.'});setRefreshCookie(res,data.session.refresh_token);res.json({token:data.session.access_token,expiresAt:data.session.expires_at});}));
