async function replaceProduct(id:string|null,b:any){const db=getSupabaseAdmin();const product={category_id:b.categoryId,name:b.name,slug:b.slug||String(b.name).toLowerCase().replace(/[^a-z0-9]+/g,'-'),description:b.description||'',base_price:Number(b.basePrice),discount_price:b.discountPrice?Number(b.discountPrice):null,weight_grams:Number(b.weightGrams),is_active:b.isActive!==false,is_archived:Boolean(b.isArchived),updated_at:new Date().toISOString()};let pid=id;if(id){const {error}=await db.from('products').update(product).eq('id',id);if(error)throw error;}else{const {data,error}=await db.from('products').insert(product).select('id').single();if(error)throw error;pid=data.id;}if(id&&(b.sizes||b.colors)){const {count}=await db.from('order_items').select('*',{count:'exact',head:true}).in('variant_id',(await db.from('product_variants').select('id').eq('product_id',pid)).data?.map((x:any)=>x.id)||[]);if(count)throw new Error('Variasi produk yang sudah memiliki pesanan tidak dapat dibentuk ulang.');await db.from('product_sizes').delete().eq('product_id',pid);await db.from('product_colors').delete().eq('product_id',pid);}const sizeIds=new Map<string,string>(),colorIds=new Map<string,string>();for(const [i,name] of (b.sizes||[]).entries()){const {data,error}=await db.from('product_sizes').insert({product_id:pid,name,sort_order:i}).select('id').single();if(error)throw error;sizeIds.set(name,data.id);}for(const [i,c] of (b.colors||[]).entries()){const {data,error}=await db.from('product_colors').insert({product_id:pid,name:c.color,hex:c.colorHex,sort_order:i}).select('id').single();if(error)throw error;colorIds.set(c.color,data.id);const gallery=(b.colorGalleries||[]).find((g:any)=>g.color===c.color);if(gallery?.images?.length){const {error:e}=await db.from('product_color_images').insert(gallery.images.map((path:string,j:number)=>({color_id:data.id,storage_path:path,sort_order:j})));if(e)throw e;}}for(const v of (b.variants||[])){const {data,error}=await db.from('product_variants').insert({product_id:pid,color_id:colorIds.get(v.color),size_id:sizeIds.get(v.size),sku:v.sku||`DFR-${crypto.randomBytes(5).toString('hex').toUpperCase()}`}).select('id').single();if(error)throw error;if(Number(v.initialStock)>0){const code=`B-${Date.now()}-${crypto.randomBytes(3).toString('hex')}`;const {error:e}=await db.rpc('restock_variant',{p_variant_id:data.id,p_quantity:Number(v.initialStock),p_cost:Number(v.costPerUnit),p_arrival:new Date().toISOString().slice(0,10),p_batch_code:code,p_actor:null});if(e)throw e;}}return repository.product(pid!);}
const normalizedProductBody=(b:any)=>({...b,colorGalleries:(b.colorGalleries||[]).map((g:any)=>({...g,images:(g.images||[]).map((x:string)=>catalogPath(x))}))});
const productRpcPayload=(input:any)=>{const b=normalizedProductBody(input);return {categoryId:b.categoryId,name:b.name,slug:b.slug||String(b.name).toLowerCase().replace(/[^a-z0-9]+/g,'-'),description:b.description||'',basePrice:Number(b.basePrice),discountPrice:b.discountPrice==null?'':String(b.discountPrice),weightGrams:Number(b.weightGrams),isActive:b.isActive!==false,sizes:(b.sizes||[]).map((name:string,i:number)=>({name,sortOrder:i})),colors:(b.colors||[]).map((c:any,i:number)=>{const g=(b.colorGalleries||[]).find((x:any)=>x.color===c.color);return {name:c.color,hex:c.colorHex,sortOrder:i,images:(g?.images||[]).map((path:string,j:number)=>({path,sortOrder:j}))};}),variants:(b.variants||[]).map((v:any)=>({...v,sku:v.sku||`DFR-${crypto.randomBytes(5).toString('hex').toUpperCase()}`,batchCode:`B-${Date.now()}-${crypto.randomBytes(3).toString('hex')}`}))};};
async function saveProductRpc(id:string|null,body:any,actor:string){
  const db=getSupabaseAdmin();
  let previousPaths:string[]=[];
  if(id){
    const {data,error}=await db.from('product_colors').select('product_color_images(storage_path)').eq('product_id',id);
    if(error)throw error;
    previousPaths=(data||[]).flatMap((color:any)=>(color.product_color_images||[]).map((image:any)=>String(image.storage_path)));
  }
  const variants=Array.isArray(body.variants)?body.variants:[];
  for(const variant of variants){
    const quantity=Number(variant.initialStock)||0;
    const cost=Number(variant.costPerUnit)||0;
    if(quantity<0||cost<0||!Number.isInteger(quantity))throw new Error('Jumlah stok dan harga modal tidak valid.');
    if(quantity>0&&cost<=0)throw new Error('Harga modal wajib lebih dari 0 jika stok diisi.');
  }
  const {data,error}=await db.rpc('save_product',{p_product_id:id,p_payload:productRpcPayload(body),p_actor:actor});
  if(error)throw error;

  // save_product membuat batch stok awal untuk produk baru. Pada produk yang
  // sudah ada, setiap angka positif merupakan restock batch baru agar FIFO dan
  // stock_movements tetap menjadi sumber kebenaran.
  if(id){
    const saved=await repository.product(data,true);
    if(!saved)throw new Error('Produk tidak ditemukan setelah diperbarui.');
    for(const requested of variants){
      const quantity=Number(requested.initialStock)||0;
      if(quantity<=0)continue;
      const variant=saved.variants.find((item:any)=>item.color===requested.color&&item.size===requested.size);
      if(!variant)throw new Error(`Variasi ${requested.color} / ${requested.size} tidak ditemukan.`);
      const batchCode=`B-${Date.now()}-${crypto.randomBytes(5).toString('hex')}`;
      const {error:restockError}=await db.rpc('restock_variant',{
        p_variant_id:variant.id,
        p_quantity:quantity,
        p_cost:Number(requested.costPerUnit),
        p_arrival:new Date().toISOString().slice(0,10),
        p_batch_code:batchCode,
        p_actor:actor
      });
      if(restockError)throw restockError;
    }
  }
  if(previousPaths.length){
    const {data:stillUsed,error:referenceError}=await db.from('product_color_images').select('storage_path').in('storage_path',previousPaths);
    if(referenceError)throw referenceError;
    const used=new Set((stillUsed||[]).map((image:any)=>String(image.storage_path)));
    const orphaned=[...new Set(previousPaths.filter((path)=>!used.has(path)))];
    if(orphaned.length)await db.storage.from('catalog-media').remove(orphaned);
  }
  return repository.product(data,true);
}
