apiRouter.delete('/admin/products/:id',asyncRoute(async(req:any,res:any)=>{
  const {data,error}=await getSupabaseAdmin().rpc('delete_product_if_unreferenced',{
    p_product_id:req.params.id,
    p_actor:res.locals.owner.id
  });
  if(error)throw error;
  if(!data?.deleted){
    if(data?.reason==='NOT_FOUND')return res.status(404).json({code:'PRODUCT_NOT_FOUND',error:'Produk tidak ditemukan.'});
    const refs=data?.references||{};
    const reasons=[];
    if(Number(refs.orders)>0)reasons.push(`${refs.orders} item pesanan`);
    if(Number(refs.reservations)>0)reasons.push(`${refs.reservations} item reservasi`);
    if(Number(refs.returns)>0)reasons.push(`${refs.returns} item retur`);
    return res.status(409).json({
      code:'PRODUCT_REFERENCED',
      error:`Produk tidak dapat dihapus karena masih tersimpan dalam ${reasons.join(', ') || 'riwayat transaksi'}. Arsipkan produk agar riwayat tetap utuh.`,
      canArchive:true,
      references:refs
    });
  }
  res.json({success:true,deleted:true});
}));
