apiRouter.post('/admin/products/stock-correction',asyncRoute(async(req:any,res:any)=>{const target=Number(req.body.targetPhysical);if(!Number.isInteger(target)||target<0||String(req.body.reason||'').trim().length<3)return res.status(400).json({error:'Stok fisik dan alasan koreksi wajib diisi dengan benar.'});const {data,error}=await getSupabaseAdmin().rpc('correct_variant_stock',{p_variant_id:req.body.variantId,p_target_physical:target,p_reason:String(req.body.reason).trim(),p_actor:res.locals.owner.id});if(error){const message=String(error.message||'');if(message.includes('STOCK_BELOW_ACTIVE_RESERVATIONS'))return res.status(409).json({error:'Stok fisik tidak boleh lebih kecil dari jumlah yang sedang ditahan reservasi aktif.'});if(message.includes('RESTOCK_REQUIRED_FOR_EMPTY_VARIANT'))return res.status(409).json({error:'Variasi belum memiliki batch modal. Gunakan Restock untuk menambahkan stok pertama.'});throw error;}res.json({success:true,correction:data});}));
apiRouter.post('/admin/products/batch-cost-correction',asyncRoute(async(req:any,res:any)=>{const cost=Number(req.body.costPerUnit);if(!Number.isFinite(cost)||cost<0||String(req.body.reason||'').trim().length<3)return res.status(400).json({error:'Harga modal dan alasan koreksi wajib diisi dengan benar.'});const {data,error}=await getSupabaseAdmin().rpc('correct_inventory_batch_cost',{p_batch_id:req.body.batchId,p_cost_per_unit:cost,p_reason:String(req.body.reason).trim(),p_actor:res.locals.owner.id});if(error){if(String(error.message||'').includes('BATCH_COST_ALREADY_USED'))return res.status(409).json({error:'Modal batch tidak dapat dikoreksi karena batch sudah dipakai pada transaksi. Snapshot HPP pesanan tetap dilindungi.'});throw error;}res.json({success:true,correction:data});}));

function voucherDto(v:any){return {id:v.id,code:v.code,promoName:v.promo_name,discountType:v.discount_type,discountValue:Number(v.discount_value),minOrderAmount:Number(v.min_order_amount),maxDiscountAmount:v.max_discount_amount==null?undefined:Number(v.max_discount_amount),scope:v.scope,quota:v.quota,reservedQuota:v.reserved_quota,usedCount:v.used_count,startDate:v.starts_at,endDate:v.ends_at,isActive:v.is_active};}
apiRouter.get('/admin/vouchers',asyncRoute(async(_q:any,res:any)=>{const {data,error}=await getSupabaseAdmin().from('vouchers').select('*').order('created_at',{ascending:false});if(error)throw error;res.json({vouchers:(data||[]).map(voucherDto)});}));
function voucherRow(b:any){return {code:b.code?.toUpperCase(),promo_name:b.promoName,discount_type:b.discountType,discount_value:Number(b.discountValue),min_order_amount:Number(b.minOrderAmount||0),max_discount_amount:b.maxDiscountAmount?Number(b.maxDiscountAmount):null,scope:b.scope||'ALL',quota:Number(b.quota),starts_at:b.startDate,ends_at:b.endDate,is_active:b.isActive!==false,updated_at:new Date().toISOString()};}
async function saveVoucher(id:string|null,body:any){const {data:idOut,error}=await getSupabaseAdmin().rpc('save_voucher',{p_id:id,p_data:body});if(error)throw error;const {data,error:e}=await getSupabaseAdmin().from('vouchers').select('*').eq('id',idOut).single();if(e)throw e;return voucherDto(data);}
apiRouter.post('/admin/vouchers',asyncRoute(async(req:any,res:any)=>res.json({voucher:await saveVoucher(null,req.body)})));
apiRouter.put('/admin/vouchers/:id',asyncRoute(async(req:any,res:any)=>res.json({voucher:await saveVoucher(req.params.id,req.body)})));
apiRouter.delete('/admin/vouchers/:id',asyncRoute(async(req:any,res:any)=>{const {error}=await getSupabaseAdmin().from('vouchers').update({is_active:false}).eq('id',req.params.id);if(error)throw error;res.json({success:true});}));

apiRouter.get('/admin/expenses',asyncRoute(async(_q:any,res:any)=>{const {data,error}=await getSupabaseAdmin().from('business_expenses').select('*').order('expense_date',{ascending:false});if(error)throw error;res.json({expenses:(data||[]).map((x:any)=>({id:x.id,category:x.category,description:x.description,amount:Number(x.amount),periodMonth:x.period_month,expenseDate:x.expense_date,receiptUrl:x.receipt_path,createdAt:x.created_at}))});}));
const expenseRow=(b:any)=>({category:b.category,description:b.description,amount:Number(b.amount),period_month:b.periodMonth,expense_date:b.expenseDate,receipt_path:b.receiptUrl||null});
apiRouter.post('/admin/expenses',asyncRoute(async(req:any,res:any)=>{const {data,error}=await getSupabaseAdmin().from('business_expenses').insert({...expenseRow(req.body),created_by:res.locals.owner.id}).select().single();if(error)throw error;res.json({expense:data});}));
apiRouter.put('/admin/expenses/:id',asyncRoute(async(req:any,res:any)=>{const {data,error}=await getSupabaseAdmin().from('business_expenses').update(expenseRow(req.body)).eq('id',req.params.id).select().single();if(error)throw error;res.json({expense:data});}));
apiRouter.delete('/admin/expenses/:id',asyncRoute(async(req:any,res:any)=>{const {error}=await getSupabaseAdmin().from('business_expenses').delete().eq('id',req.params.id);if(error)throw error;res.json({success:true});}));

apiRouter.post('/admin/upload-media',upload.single('file'),asyncRoute(async(req:any,res:any)=>{if(!req.file)return res.status(400).json({error:'File wajib dipilih.'});const path=await uploadFile('catalog-media',req.file,'media');res.json({url:publicStorageUrl(path),path});}));
apiRouter.post('/admin/upload-media-multiple',upload.array('files',12),asyncRoute(async(req:any,res:any)=>{const paths=[];for(const f of (req.files as Express.Multer.File[]||[]))paths.push(await uploadFile('catalog-media',f,'media'));res.json({urls:paths.map(publicStorageUrl),paths});}));
apiRouter.post('/admin/upload-banner',upload.single('file'),asyncRoute(async(req:any,res:any)=>{if(!req.file)return res.status(400).json({error:'File banner wajib dipilih.'});const path=await uploadFile('catalog-media',req.file,'banners');res.json({url:publicStorageUrl(path),path});}));

apiRouter.get('/admin/orders',asyncRoute(async(_q:any,res:any)=>{const {data,error}=await getSupabaseAdmin().from('orders').select('*,order_items(*,order_fifo_allocations(*)),payments(*),order_costs(*)').order('created_at',{ascending:false});if(error)throw error;res.json({orders:(data||[]).map(orderDto)});}));
apiRouter.get('/admin/orders/:orderNumber',asyncRoute(async(req:any,res:any)=>{const {data,error}=await getSupabaseAdmin().from('orders').select('*,order_items(*,order_fifo_allocations(*)),payments(*),order_costs(*)').eq('order_number',req.params.orderNumber).maybeSingle();if(error)throw error;if(!data)return res.status(404).json({error:'Pesanan tidak ditemukan.'});for(const p of data.payments||[])p.signedUrl=(await getSupabaseAdmin().storage.from(p.proof_bucket).createSignedUrl(p.proof_path,300)).data?.signedUrl;res.json({order:orderDto(data)});}));
apiRouter.get('/admin/orders/:orderNumber/invoice',asyncRoute(async(req:any,res:any)=>{
  const {data:order,error}=await getSupabaseAdmin().from('orders').select(invoiceOrderSelect).eq('order_number',req.params.orderNumber).eq('payment_status','VERIFIED').maybeSingle();
  if(error)throw error;
  if(!order)return res.status(409).json({error:'Invoice tersedia setelah pembayaran diverifikasi admin.'});
  const pdf=await createInvoicePdf(order);
  res.setHeader('Cache-Control','private, no-store');
  res.setHeader('Content-Type','application/pdf');
  res.setHeader('Content-Disposition',`attachment; filename="invoice-${req.params.orderNumber.replace(/[^A-Za-z0-9_-]/g,'')}.pdf"`);
  res.send(pdf);
}));
apiRouter.post('/admin/orders/:orderNumber/verify-payment',asyncRoute(async(req:any,res:any)=>{const {data:o,error}=await getSupabaseAdmin().from('orders').update({payment_status:req.body.verified===false?'REVISION_REQUESTED':'VERIFIED',rejection_reason:req.body.reason||null,rejection_deadline:req.body.deadline||null,updated_at:new Date().toISOString()}).eq('order_number',req.params.orderNumber).select('id').single();if(error)throw error;await getSupabaseAdmin().from('payments').update({status:req.body.verified===false?'REVISION_REQUESTED':'VERIFIED',verified_at:req.body.verified===false?null:new Date().toISOString(),verified_by:res.locals.owner.id}).eq('order_id',o.id);res.json({success:true});}));
apiRouter.post('/admin/orders/:orderNumber/update-fulfillment',asyncRoute(async(req:any,res:any)=>{const patch:any={fulfillment_status:req.body.fulfillmentStatus,tracking_number:req.body.trackingNumber||null,updated_at:new Date().toISOString()};if(req.body.fulfillmentStatus==='DELIVERED')patch.actual_delivery_date=req.body.actualDeliveryDate||new Date().toISOString().slice(0,10);const {error}=await getSupabaseAdmin().from('orders').update(patch).eq('order_number',req.params.orderNumber);if(error)throw error;res.json({success:true});}));
apiRouter.post('/admin/orders/:orderNumber/cancel',asyncRoute(async(req:any,res:any)=>{const {error}=await getSupabaseAdmin().rpc('cancel_order_restore_stock',{p_order_number:req.params.orderNumber,p_reason:req.body.reason,p_actor:res.locals.owner.id});if(error)throw error;res.json({success:true});}));
apiRouter.post('/admin/orders/:orderNumber/refund',asyncRoute(async(req:any,res:any)=>{const {error}=await getSupabaseAdmin().rpc('record_order_refund',{p_order_number:req.params.orderNumber,p_amount:Number(req.body.amount),p_reason:req.body.reason,p_actor:res.locals.owner.id});if(error)throw error;res.json({success:true});}));
apiRouter.delete('/admin/orders/:orderNumber',asyncRoute(async(req:any,res:any)=>{
  const {data,error}=await getSupabaseAdmin().rpc('delete_unpaid_test_order',{p_order_number:req.params.orderNumber,p_actor:res.locals.owner.id});
  if(error)throw error;
  if(!data?.deleted){
    if(data?.reason==='NOT_FOUND')return res.status(404).json({code:'ORDER_NOT_FOUND',error:'Pesanan tidak ditemukan.'});
    return res.status(409).json({code:'FINANCIAL_HISTORY_PROTECTED',error:'Pesanan memiliki pembayaran, refund, retur, atau proses pengiriman sehingga riwayatnya wajib dipertahankan. Gunakan pembatalan/status yang sesuai.'});
  }
  for(const proof of data.proofs||[]){
    if(proof?.bucket&&proof?.path)await getSupabaseAdmin().storage.from(proof.bucket).remove([proof.path]);
  }
  res.json({success:true,deleted:true});
}));
apiRouter.get('/admin/returns',asyncRoute(async(_q:any,res:any)=>{
  const db=getSupabaseAdmin();
  const {data,error}=await db.from('return_requests').select('*,orders(order_number),return_items(*),return_proofs(*)').order('created_at',{ascending:false});
  if(error)throw error;
  const returns=await Promise.all((data||[]).map(async(x:any)=>{
    const proofImageUrls=(await Promise.all((x.return_proofs||[]).map(async(proof:any)=>{
      const {data:signed,error:signedError}=await db.storage.from(proof.bucket||'return-proofs').createSignedUrl(proof.storage_path,900);
      if(signedError)return null;
      return signed?.signedUrl||null;
    }))).filter(Boolean);
    return {id:x.id,orderId:x.order_id,orderNumber:x.orders?.order_number,returnNumber:x.return_number,requestedResolution:x.requested_resolution,reasonCategory:x.reason_category,customerNotes:x.customer_notes,status:x.status,adminNotes:x.admin_notes,inspectionResult:x.inspection_result,receivedDate:x.received_at,resolvedDate:x.resolved_at,createdAt:x.created_at,proofImageUrls};
  }));
  res.setHeader('Cache-Control','private, no-store');
  res.json({returns});
}));
apiRouter.post('/admin/returns/:returnNumber/status',asyncRoute(async(req:any,res:any)=>{const {error}=await getSupabaseAdmin().rpc('update_return_status',{p_return_number:req.params.returnNumber,p_status:req.body.status,p_admin_notes:req.body.adminNotes||null,p_inspection:req.body.inspectionResult||null,p_actor:res.locals.owner.id});if(error)throw error;res.json({success:true});}));

