apiRouter.get('/admin/financial-export',asyncRoute(async(req:any,res:any)=>{const from=String(req.query.startDate||'1970-01-01'),to=String(req.query.endDate||'2999-12-31');const {data,error}=await getSupabaseAdmin().from('orders').select('order_number,created_at,subtotal,discount_amount,shipping_fee,total_amount,refund_amount,payment_status,fulfillment_status').gte('created_at',from).lte('created_at',`${to}T23:59:59.999Z`).order('created_at');if(error)throw error;const esc=(v:any)=>`"${String(v??'').replace(/"/g,'""')}"`;const rows=[['Nomor Pesanan','Tanggal','Subtotal','Diskon','Ongkir','Total','Refund','Status Pembayaran','Status Pengiriman'],...(data||[]).map((o:any)=>[o.order_number,o.created_at,o.subtotal,o.discount_amount,o.shipping_fee,o.total_amount,o.refund_amount,o.payment_status,o.fulfillment_status])];res.setHeader('Content-Type','text/csv; charset=utf-8');res.setHeader('Content-Disposition','attachment; filename="laporan-defra.csv"');res.send('\uFEFF'+rows.map(r=>r.map(esc).join(',')).join('\n'));}));

