apiRouter.post('/admin/telegram/test',asyncRoute(async(_q:any,res:any)=>{const bot=process.env.TELEGRAM_BOT_TOKEN?.trim(),chat=process.env.TELEGRAM_CHAT_ID?.trim();if(!bot||!chat)return res.status(400).json({error:'Telegram belum dikonfigurasi di ENV server.'});try{await sendTelegramMessage(bot,chat,'Tes notifikasi Defra Hijab berhasil. Pesan ini dikirim manual dari panel owner.');res.json({success:true,delivered:true,message:'Telegram menerima pesan tes.'});}catch(error){res.status(502).json({success:false,delivered:false,error:String((error as Error).message||'Telegram menolak pesan tes.').replaceAll(bot,'[TOKEN DISEMBUNYIKAN]').slice(0,300)});}}));
