apiRouter.use((err:any,_req:express.Request,res:express.Response,_next:express.NextFunction)=>{if(err instanceof multer.MulterError)return res.status(400).json({error:err.code==='LIMIT_FILE_SIZE'?'Ukuran file maksimal 2 MB.':err.message});if(err?.status===400)return res.status(400).json({error:err.message});console.error('[api]',err?.message||err);res.status(500).json({error:'Terjadi kendala pada server.'});});
